#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto apply = [&](int x, int y){
        ops.push_back({x,y});
        // [A|B|C] -> [C|B|A], |A|=x, |C|=y
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
    };

    for(int target=0; target<n-1; target++){
        int pos=-1;
        for(int i=target;i<n;i++) if(p[i]==target+1){pos=i;break;}
        if(pos==target) continue;

        int remaining = n - target; // elements from target..n-1 are unsorted
        // We work on subarray [target..n-1], but operations are global.
        // Move element from pos to position target.

        if(pos == n-1){
            // Element is at last position. Use y=1, x = n-1-target. 
            // x+y = n-target, need ≤ n-1 → target ≥ 1
            if(target >= 1){
                apply(n-1-target, 1); // element at n-1 in C, goes to pos 0. But we want target.
                // Actually goes to position 0. Then first target elements are already sorted and got moved to end.
                // Hmm, this disrupts sorted prefix. Let me use x=target, then sorted prefix stays as middle.
                // Undo and rethink...
            }
        }

        // General: first move to end, then from end to target
        if(pos < n-1){
            int y1 = n-1-pos; // x1=1, element at pos in middle goes to pos-1+y1 = n-2... no
            // To move pos to n-1: put it in A. x=pos+1, y=1 (if valid). Goes to n-x+pos = n-1.
            if(pos+1+1 <= n-1){ apply(pos+1,1); pos=n-1; }
            else { apply(1, n-1-pos); pos = n-1; } // might not always work
        }
        if(pos==n-1 && target < n-1){
            // y = n-1-target, x = target. x+y=n-1. Element at n-1 in C goes to 0... 
            // C starts at n-y = target+1. n-1 >= target+1 if n>=target+2, yes. Goes to (n-1)-(target+1)= n-2-target? No: position in output = pos - (n-y) = n-1-n+y = y-1 = n-2-target.
            // That's not target. Use x=n-1-target, y=target+1. x+y=n, too big.
            apply(target, n-1-target); // x=target,y=n-1-target. elem at n-1 in C(starts at target+1). goes to n-1-(target+1)=n-2-target. Not right.
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
